oracles.script:
const mod = await loadModule("./src/calc.js");
const cases = [[3, 4, 7], [0, 0, 0], [-2, 5, 3], [100, 250, 350], [-7, -3, -10]];
const failures = [];
for (const [a, b, expected] of cases) {
  let got;
  try { got = mod.add(a, b); } catch (error) { got = "threw: " + error; }
  if (got !== expected) failures.push(`add(${a},${b}) expected ${expected}, got ${got}`);
}
console.log("oracle-result: " + JSON.stringify({ passed: failures.length === 0, detail: failures.length ? failures.join("; ") : "all addition cases pass" }));

const mod = await loadModule("./src/calc.js");
const ok = typeof mod.add === "function";
console.log("oracle-result: " + JSON.stringify({ passed: ok, detail: ok ? "module loads and exports add" : "add export missing" }));
